package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;

public class JsonWriter_value_TriageGen1Test {

    private StringWriter out;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        out = new StringWriter();
        jsonWriter = new JsonWriter(out);
    }







    @Test
    public void testValueWithChaining() throws IOException {
        // Arrange
        jsonWriter.beginObject();
        jsonWriter.name("a");

        // Act & Assert
        jsonWriter.value(true).name("b").value(false);

        assertEquals("{\"a\":true,\"b\":false}", out.toString());
    }
}
